UPDATE pacientes SET sexo = 'M'
WHERE usuario_id IN (SELECT id FROM usuarios WHERE email IN ('juan.perez@correo.com', 'carlos.mendoza@correo.com', 'diego.herrera@correo.com', 'luis.vargas@correo.com', 'jorge.medina@correo.com'));

UPDATE pacientes SET sexo = 'F'
WHERE usuario_id IN (SELECT id FROM usuarios WHERE email IN ('maria.rodriguez@correo.com', 'sofia.ramirez@correo.com', 'valeria.castillo@correo.com', 'camila.torres@correo.com', 'ana.paredes@correo.com'));

INSERT INTO atencion_diagnosticos (atencion_id, cie10_id, codigo, descripcion, tipo, principal, observacion, posicion)
SELECT a.id, c.id, c.codigo, c.descripcion, 'DEFINITIVO', true, NULL, 0
FROM atenciones a
JOIN catalogo_cie10 c ON c.codigo = CASE
    WHEN a.diagnostico LIKE 'Paciente sana%' THEN 'Z00.0'
    WHEN a.diagnostico LIKE 'Hipertensión arterial%' THEN 'I10'
    WHEN a.diagnostico LIKE 'Acné vulgar%' THEN 'L70.0'
    WHEN a.diagnostico LIKE 'Esguince de rodilla%' THEN 'S83.4'
    WHEN a.diagnostico LIKE 'Control ginecológico%' THEN 'Z01.4'
    WHEN a.diagnostico LIKE 'Fatiga visual%' THEN 'H53.1'
    WHEN a.diagnostico LIKE 'Léntigos solares%' THEN 'L81.4'
    END;

UPDATE ingresos_hospitalarios h
SET cie10_ingreso_codigo = c.codigo, cie10_ingreso_descripcion = c.descripcion
FROM catalogo_cie10 c
WHERE (h.codigo = 'HOS-000001' AND c.codigo = 'I50.0')
   OR (h.codigo = 'HOS-000002' AND c.codigo = 'S82.2')
   OR (h.codigo = 'HOS-000005' AND c.codigo = 'A09');

UPDATE ingresos_hospitalarios h
SET cie10_alta_codigo = c.codigo, cie10_alta_descripcion = c.descripcion
FROM catalogo_cie10 c
WHERE h.codigo = 'HOS-000005' AND c.codigo = 'A09';
